   78	// Middleware recovers panics in next, writes a report for each, and
   79	// answers 500. It also tracks requests in flight for Watch.
   80	func (rep *Reporter) Middleware(next http.Handler) http.Handler {
   81		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
   82			f := &inflight{start: rep.Now(), req: requestOf(r), body: new(bytes.Buffer)}
   83			if r.Body != nil {
   84				r.Body = struct {
   85					io.Reader
   86					io.Closer
   87				}{io.TeeReader(r.Body, &limitedWriter{f.body, maxBody}), r.Body}
   88			}
   89			rep.mu.Lock()
   90			rep.inflight[f] = struct{}{}
   91			rep.mu.Unlock()
   92			defer func() {
   93				rep.mu.Lock()
   94				delete(rep.inflight, f)
   95				rep.mu.Unlock()
   96				if v := recover(); v != nil {
   97					if err, ok := v.(error); ok && errors.Is(err, http.ErrAbortHandler) {
   98						panic(v)
   99					}
  100					req := f.req
  101					req.Body = f.body.String()
  102					rep.write("panic", fmt.Sprint(v), string(debug.Stack()), req)
  103					http.Error(w, "internal error", http.StatusInternalServerError)
  104				}
  105			}()
  106			next.ServeHTTP(w, r)
  107		})
  108	}
