  111	// oldest request that has been in flight longer than limit and hasn't
  112	// been reported yet.
  113	func (rep *Reporter) Check(limit time.Duration) bool {
  114		now := rep.Now()
  115		rep.mu.Lock()
  116		var oldest *inflight
  117		for f := range rep.inflight {
  118			if !f.reported && now.Sub(f.start) > limit && (oldest == nil || f.start.Before(oldest.start)) {
  119				oldest = f
  120			}
  121		}
  122		if oldest != nil {
  123			oldest.reported = true
  124		}
  125		rep.mu.Unlock()
  126		if oldest == nil {
  127			return false
  128		}
  129		var dump bytes.Buffer
  130		if err := pprof.Lookup("goroutine").WriteTo(&dump, 2); err != nil {
  131			dump.WriteString(err.Error())
  132		}
  133		rep.write("stuck", fmt.Sprintf("request in flight for %s", now.Sub(oldest.start).Round(time.Second)), dump.String(), oldest.req)
