  142			ID:        fmt.Sprintf("crash-%06d", rep.seq),
  143			Kind:      kind,
  144			Time:      rep.Now(),
  145			Service:   rep.Service,
  146			Version:   rep.Version,
  147			Commit:    rep.Commit,
  148			GoVersion: runtime.Version(),
  149			Panic:     value,
  150			Stack:     stack,
  151			Request:   req,
  152		}
  153		if rep.Logs != nil {
  154			r.Logs = rep.Logs.Lines()
  155		}
  156		// A crash report that can't be written has nowhere else to go.
  157		_ = json.NewEncoder(rep.w).Encode(r)
  158	}
