  160	func requestOf(r *http.Request) Request {
  161		req := Request{
  162			Method:  r.Method,
  163			Path:    r.URL.Path,
  164			Query:   r.URL.RawQuery,
  165			Headers: make(map[string]string, len(r.Header)),
  166		}
  167		for k, v := range r.Header {
